// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address creator = address(this);
        address attacker = address(0x1234);
        vm.deal(creator, 1);
        vm.prank(creator);
        c.deposit{value: 1}();
        vm.deal(attacker, 0);
        vm.prank(attacker);
        bool ok;
        try c.migrateTo(attacker) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
